export class Entity {
    public id: number = Entity.seq_no++;
    public LABEL: string = "entity" + this.id;

    // Hierarchy Connections:
    public parent: Entity | null = null;
    public children: Entity[] = [];

    // Spatial & Shading States:
    public state: State = new State();
    public transform: Transform = this.state.transform;
    public paint: Paint = this.state.paint;
    public material: Material = this.state.material;

    // Direct Component Slots for O(1) Fast-Path Execution:
    public geometryComponent: GeometryComponent | null = null;
    public rendererComponent: RendererComponent | null = null;
    public fragmentComponent: FragmentComponent | null = null;
    public interactionComponent: InteractionComponent | null = null;

    // Pipeline Flags:
    public VISIBILITY: boolean = true;
    public CAST_SHADOW: boolean = false;
    public RECEIVE_SHADOW: boolean = false;
    public RT_ENABLE: boolean = false;
    public isPickable: boolean = false;
    public layerMask: number = 1;
    public scissorClipRect: { width: number, height: number, offsetX: number, offsetY: number } | null = null;
}

