import { Scene, Circle, Group, Color, Vec3 } from "retiam";

export class SolarSystemScene extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 100]);

        // 1. Sun (Root Node)
        const sun = new Circle(8, { fill: new Color(1.0, 0.8, 0.1, 1.0) });
        this.add(sun);

        // 2. Earth Pivot Group (Controls Earth Orbit)
        const earthOrbitGroup = new Group();
        sun.add(earthOrbitGroup);

        // 3. Earth Entity (Offset from Sun)
        const earth = new Circle(3, { fill: new Color(0.2, 0.6, 1.0, 1.0) });
        earth.transform.position.set(35, 0, 0);
        earthOrbitGroup.add(earth);

        // 4. Moon Pivot Group (Controls Moon Orbit around Earth)
        const moonOrbitGroup = new Group();
        earth.add(moonOrbitGroup);

        // 5. Moon Entity (Offset from Earth)
        const moon = new Circle(1, { fill: new Color(0.8, 0.8, 0.8, 1.0) });
        moon.transform.position.set(8, 0, 0);
        moonOrbitGroup.add(moon);

        // 6. Frame Animation Loop
        this.always(() => {
            const time = this.time * 0.001;

            // Rotate Earth orbit around Sun:
            earthOrbitGroup.transform.rotation.z = time * 0.5;

            // Rotate Moon orbit around Earth:
            moonOrbitGroup.transform.rotation.z = time * 2.5;

            this.invalidate();
        });
    }
}

import { Scene, Group, Circle, Color } from "retiam";

export class ScissorClipScene extends Scene {
    public async run() {
        // Create a parent container with a 40x40 local scissor clip rectangle
        const container = new Group();
        container.scissorClipRect = {
            width: 40,
            height: 40,
            offsetX: -20,
            offsetY: -20
        };
        this.add(container);

        // Nested circles that move outside the 40x40 box are clipped at the hardware level:
        const circle = new Circle(10, { fill: Color.RED });
        container.add(circle);

        this.always(() => {
            circle.transform.position.x = Math.sin(this.time * 0.002) * 35;
            this.invalidate();
        });
    }
}

import { Entity, Vec3 } from "retiam";

const myEntity = new Entity();

// Add a per-frame updater hook attached directly to the entity:
myEntity.addUpdater((time, dt) => {
    myEntity.transform.position.y += Math.sin(time * 0.005) * 0.1;
    myEntity.transform.rotation.z += dt * 0.001;
});
